// =============================================================================
// Quorum Setup (edit me) — normal path: edit literals in this node only.
// No n8n container env vars. No NODE_FUNCTION_ALLOW_BUILTIN. No restart.
//
// ID glossary (do not mix these up):
//   n8n workflow ID     — from the n8n URL …/workflow/{id} (NOT used for signing)
//   Quorum workflow ID  — from Quorum Workflows / Protect / credential page
//   Key ID              — from Quorum “Issue push credential”
//   HMAC secret         — store in Crypto credential (≥2.7) or Crypto HMAC Secret field
// =============================================================================

const CONFIG = {
  // Quorum base URL (no trailing slash), e.g. http://host.docker.internal:3000
  quorumBaseUrl: 'REPLACE_QUORUM_BASE_URL',
  // Quorum workflow ID — NOT the n8n workflow ID from the n8n URL
  quorumWorkflowId: 'REPLACE_QUORUM_WORKFLOW_ID',
  // Key ID from Quorum push credential
  keyId: 'REPLACE_KEY_ID',
};

// Advanced Docker/K8s only: set the same names as process env and uncomment:
// CONFIG.quorumBaseUrl = String($env.QUORUM_BASE_URL || CONFIG.quorumBaseUrl).trim();
// CONFIG.quorumWorkflowId = String($env.QUORUM_WORKFLOW_ID || CONFIG.quorumWorkflowId).trim();
// CONFIG.keyId = String($env.QUORUM_KEY_ID || CONFIG.keyId).trim();
// (n8n 2.x may also need N8N_BLOCK_ENV_ACCESS_IN_NODE=false for $env.)

function requireConfig(fieldName, label, value) {
  const s = value == null ? '' : String(value).trim();
  if (!s || s.startsWith('REPLACE_')) {
    throw new Error(
      `Missing ${label} (CONFIG.${fieldName}) in node "Quorum Setup (edit me)". ` +
        'Set Quorum base URL, Quorum workflow ID (not the n8n workflow ID from the n8n URL), and Key ID. ' +
        'HMAC secret belongs on the Crypto HMAC node Secret field or a Crypto credential — not in this node.',
    );
  }
  return s;
}

const quorumBaseUrl = requireConfig('quorumBaseUrl', 'Quorum base URL', CONFIG.quorumBaseUrl).replace(/\/+$/, '');
const quorumWorkflowId = requireConfig('quorumWorkflowId', 'Quorum workflow ID', CONFIG.quorumWorkflowId);
const keyId = requireConfig('keyId', 'Key ID', CONFIG.keyId);

const path = `/api/v1/workflows/${quorumWorkflowId}/heartbeats`;

const bodyObj = {
  schemaVersion: 1,
  executedAt: new Date().toISOString(),
  status: 'success',
  itemsProcessed: 1,
  externalExecutionRef: `n8n-${Date.now()}`,
};
const bodyRaw = JSON.stringify(bodyObj);
const timestampSeconds = String(Math.floor(Date.now() / 1000));
const idempotencyKey = `n8n-${timestampSeconds}-${Math.random().toString(16).slice(2)}`;

return [{
  json: {
    url: `${quorumBaseUrl}${path}`,
    path,
    bodyRaw,
    keyId,
    timestampSeconds,
    idempotencyKey,
  },
}];

// Canonical signing payload (must match Quorum heartbeat-hmac.ts):
// ["POST", path, timestampSeconds, idempotencyKey, bodySha256Hex].join("\n")
const bodySha256Hex = $json.bodySha256Hex;
if (!bodySha256Hex || typeof bodySha256Hex !== 'string') {
  throw new Error('Missing bodySha256Hex from Hash Body SHA256 Crypto node');
}

const signingPayload = [
  'POST',
  $json.path,
  $json.timestampSeconds,
  $json.idempotencyKey,
  bodySha256Hex,
].join('\n');

return [{
  json: {
    ...$json,
    signingPayload,
  },
}];
